//! The laws of projectmd as executable properties (testdata/conformance/README.md, part 2).
//!
//! Plans are generated by a deterministic xorshift generator (no dependencies): 300 two-file plans
//! per law (a parent with a link to a child). Failures print the seed index and both files.

use pmd_core::*;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

const PLANS: u64 = 300;

struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Rng {
        Rng(seed.wrapping_mul(0x9E37_79B9_7F4A_7C15) | 1)
    }
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }
    fn range(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

/// A child with a Commitment, a few exposed milestones and private work; and a parent that links
/// to it as a sub-project and as a deliverable of one milestone.
struct Plan {
    child: String,
    parent: String,
    /// Index of the exposed milestone the parent's deliverable points at, and its month.
    target: usize,
    months: Vec<u64>,
}

fn plan(seed: u64) -> Plan {
    let mut r = Rng::new(seed + 1);
    let n_ms = 2 + r.range(3) as usize;
    let mut months = Vec::new();
    let mut child = String::from("# Child\n\n- Owner: Bob\n");
    child.push_str(&format!("- Commitment: 2027-{:02}-28\n\n", 10 + r.range(2)));
    for i in 0..n_ms {
        let m = 2 + r.range(9);
        months.push(m);
        child.push_str(&format!("- [ ] 2027-{:02}-{:02} Gate {}  ^m{}\n", m, 1 + r.range(28), i, i));
        if r.range(2) == 0 {
            child.push_str(&format!("- [ ] Work {}  {}w  after: ^m{}\n", i, 1 + r.range(3), i));
        }
    }
    child.push_str("- [ ] Private task  2w\n");
    let target = r.range(n_ms as u64) as usize;
    let parent = format!(
        "# Parent\n\n- Owner: Ann\n\n- [ ] [Child](child.md)  by: 2027-12-31  ^c\n- [ ] [Child gate](child.md#m{})  by: 2027-11-30  ^d\n- [ ] Integrate  1w  after: ^d\n",
        target
    );
    Plan { child, parent, target, months }
}

/// Parent JSON after scheduling it with the two files loaded in the given order.
fn schedule_parent(parent: &str, child: &str, today: &str, child_first: bool) -> String {
    let today_d = match parse_date(today) {
        DateParse::Ok(c, _) => c,
        _ => panic!("bad today"),
    };
    let pp = parse("parent.md", parent);
    let cp = parse("child.md", child);
    let mut g = Graph::new("parent.md");
    if child_first {
        g.add(cp);
        g.add(pp);
    } else {
        g.add(pp);
        g.add(cp);
    }
    let mut ifs = Interfaces::new();
    for p in g.projects() {
        ifs.insert(normalize(&p.path), Interface::from_project(p));
    }
    let ps: Vec<(String, &Project)> = g.projects().iter().map(|p| (normalize(&p.path), p)).collect();
    add_forecasts(&mut ifs, &ps, today_d);
    let mut p = g.get("parent.md").expect("parent").clone();
    schedule(&mut p, today_d, &ifs);
    serde_json::to_string(&p).unwrap()
}

const TODAY: &str = "2027-03-01";

/// Lines that add nothing to the child's interface: a private undated task, a description under
/// the last item, a #private milestone after the last one. None is a milestone another file reads.
fn private_mutation(child: &str, k: usize) -> String {
    let mut s = child.to_string();
    match k % 3 {
        0 => s.push_str(&format!("- [ ] Scratch note {}  ^note{}\n", k, k)),
        1 => s.push_str("  Free text about the private plan.\n"),
        _ => s.push_str(&format!("- [ ] 2027-12-31 Secret {}  #private  ^sec{}\n", k, k)),
    }
    s
}

#[test]
fn locality_private_edits_do_not_change_the_parent() {
    for i in 0..PLANS {
        let p = plan(i);
        let base = schedule_parent(&p.parent, &p.child, TODAY, false);
        let mut child = p.child.clone();
        for k in 0..3 {
            child = private_mutation(&child, i as usize + k);
            let after = schedule_parent(&p.parent, &child, TODAY, false);
            assert_eq!(base, after, "plan {} changed the parent after a private edit\n{}", i, child);
        }
    }
}

#[test]
fn locality_is_not_vacuous_moving_an_exposed_date_changes_the_parent() {
    for i in 0..PLANS {
        let p = plan(i);
        let base = schedule_parent(&p.parent, &p.child, TODAY, false);
        // move the milestone the parent's deliverable reads to another month (always a different one)
        let m = p.months[p.target];
        let new_m = if m < 12 { m + 1 } else { m - 1 };
        let old = format!("2027-{:02}-", m);
        let new = format!("2027-{:02}-", new_m);
        let line = p.child.lines().find(|l| l.contains(&format!("^m{}", p.target))).unwrap().to_string();
        let moved = line.replacen(&old, &new, 1);
        let child = p.child.replacen(&line, &moved, 1);
        let after = schedule_parent(&p.parent, &child, TODAY, false);
        assert_ne!(base, after, "plan {}: moving an exposed milestone left the parent unchanged\n{}", i, p.child);
    }
}

#[test]
fn derivation_is_order_independent_and_repeatable() {
    for i in 0..PLANS {
        let p = plan(i);
        let a = schedule_parent(&p.parent, &p.child, TODAY, false);
        let b = schedule_parent(&p.parent, &p.child, TODAY, false);
        let c = schedule_parent(&p.parent, &p.child, TODAY, true);
        assert_eq!(a, b, "plan {}: scheduling twice differs", i);
        assert_eq!(a, c, "plan {}: loading the files in the other order differs", i);
    }
}

fn pmd_bin() -> PathBuf {
    let bin = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../target/release/pmd");
    assert!(bin.exists(), "build the reference binary first: cd parser && cargo build --release");
    bin
}

fn run(bin: &Path, dir: &Path, args: &[&str]) {
    let st = Command::new(bin).current_dir(dir).args(args).output().expect("run pmd");
    assert!(st.status.code().is_some(), "pmd {:?} did not exit normally", args);
}

/// Bytes of every file in `dir` except `named`, to check that no other file changed.
fn others(dir: &Path, named: &str) -> Vec<(String, Vec<u8>)> {
    let mut v: Vec<(String, Vec<u8>)> = fs::read_dir(dir)
        .unwrap()
        .filter_map(|e| e.ok().map(|e| e.file_name().to_string_lossy().to_string()))
        .filter(|n| n != named)
        .map(|n| (n.clone(), fs::read(dir.join(&n)).unwrap()))
        .collect();
    v.sort();
    v
}

#[test]
fn ownership_fmt_and_replan_write_only_their_file() {
    let bin = pmd_bin();
    let root = std::env::temp_dir().join(format!("pmd-laws-{}", std::process::id()));
    for i in 0..PLANS {
        let p = plan(i);
        let dir = root.join(format!("p{}", i));
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("parent.md"), &p.parent).unwrap();
        fs::write(dir.join("child.md"), &p.child).unwrap();
        fs::write(dir.join("other.md"), "# Other\n\n- Owner: Cy\n\n- [ ] Work  1w\n").unwrap();

        let before = others(&dir, "parent.md");
        run(&bin, &dir, &["fmt", "parent.md"]);
        assert_eq!(others(&dir, "parent.md"), before, "plan {}: fmt parent.md changed another file", i);

        let before = others(&dir, "parent.md");
        run(&bin, &dir, &["replan", "parent.md", "--write", "--today", TODAY]);
        assert_eq!(others(&dir, "parent.md"), before, "plan {}: replan --write changed another file", i);

        let before = others(&dir, "child.md");
        run(&bin, &dir, &["fmt", "child.md"]);
        assert_eq!(others(&dir, "child.md"), before, "plan {}: fmt child.md changed another file", i);
        fs::remove_dir_all(&dir).ok();
    }
    fs::remove_dir_all(&root).ok();
}

/// Same owner: the forecast flows across the link (D69). The child's Gate is a point on its
/// Design's end (03-07); a deliverable to it takes that forecast. Different owner: the declared
/// date (06-01) crosses instead.
#[test]
fn same_owner_forecasts_flow_across_the_link() {
    let child = "# Child\n\n- Owner: Ann\n\n- [ ] Design  1w  ^d0\n- [ ] 2027-06-01 Gate  after: ^d0  ^g\n";
    let end = |owner: &str| -> String {
        let parent = format!("# Parent\n\n- Owner: {}\n\n- [ ] [Gate](child.md#g)  ^d\n", owner);
        let v: serde_json::Value = serde_json::from_str(&schedule_parent(&parent, child, TODAY, false)).unwrap();
        v["nodes"][0]["forecast"]["end"].as_str().unwrap().to_string()
    };
    assert_eq!(end("Ann"), "2027-03-07");
    assert_eq!(end("Bob"), "2027-06-01");
}
